        login_user_block(None, ['ssh-rsa...'])
        == {'create_password': 'yes', 'ssh_keys': {'ssh_key': ['ssh-rsa...']}}
    );;
}

test "t1" {
    assert (
        login_user_block('', ['ssh-rsa...'])
        == {'create_password': 'yes', 'ssh_keys': {'ssh_key': ['ssh-rsa...']}}
    );;
}

